export type CardType = "visa" | "mastercard" | "amex" | "discover" | "paypal" | "unknown";

export interface CreditCardValues {
  cardholderName: string;
  cardNumber: string;
  expiryMonth: string;
  expiryYear: string;
  cvv: string;
}

export interface PaymentMethod {
  id: string;
  type: CardType;
  last4?: string;
  expiryMonth?: number;
  expiryYear?: number;
  email?: string;
  isDefault: boolean;
}
